"use client";
import Breadcrumb from "@/components/header/breadcrumb";
import sendReviewConsultantForm from "@/services/reviewConsultantService";
import { useState } from "react";
import { MaskedInput, createDefaultMaskGenerator } from "react-hook-mask";

const CONSULTANTS = [
  { value: "1", label: "Arda ARI" },
  { value: "2", label: "Beril KILIC" },
  { value: "3", label: "Damla KALENDER" },
  { value: "4", label: "Derya BUYUKGOL" },
  { value: "5", label: "Elif KASIKCI" },
  { value: "6", label: "Ezgi ASLAN" },
  { value: "7", label: "Gizem TILBE" },
  { value: "15", label: "Gokhan AKGOZLU" },
  { value: "8", label: "Gulgun OSMANOGLU" },
  { value: "18", label: "Gulnar KHALILOVA" },
  { value: "17", label: "Jasmine FERNANDES" },
  { value: "9", label: "Murtaza KALENDER" },
  { value: "10", label: "Orhan KALENDER" },
  { value: "11", label: "Ozcan AYTAC" },
  { value: "12", label: "Samet TEKIN" },
  { value: "13", label: "Seda MUTLU" },
  { value: "14", label: "Songul GUN" },
  { value: "16", label: "Umit TEMIZ" },
  { value: "0", label: "Other" },
];

const BOOKING_OPTIONS = [
  { value: "1", label: "Yes" },
  { value: "3", label: "Pending" },
  { value: "4", label: "Request Canceled" },
  { value: "5", label: "Booking With Other DMC" },
];

const QUESTIONS = [
  {
    key: "question1",
    label: "Was your inquiry responded to in a timely manner?",
  },
  {
    key: "question2",
    label: "Did you receive a response that met your request?",
  },
  { key: "question3", label: "How would you rate the price we provided?" },
  {
    key: "question4",
    label: "How would you describe our tour consultant approach towards you?",
  },
];

const labelCls =
  "tw-block tw-mb-1.5 tw-text-sm tw-font-semibold tw-text-[#14101c]";
const inputCls =
  "tw-w-full tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-px-3.5 tw-py-2.5 tw-text-sm tw-text-[#14101c] tw-outline-none tw-transition focus:tw-border-[#854ec9] focus:tw-shadow-[0_0_0_3px_rgba(133,78,201,0.12)]";

function RequiredMark() {
  return <span className="tw-text-[#d6336c]">*</span>;
}

function RatingScale({
  name,
  value,
  onChange,
}: {
  name: string;
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <div className="tw-flex tw-flex-wrap tw-gap-2">
      {[1, 2, 3, 4, 5].map((n) => {
        const active = parseInt(value) === n;
        return (
          <label
            key={n}
            className={`tw-flex tw-h-12 tw-w-12 tw-cursor-pointer tw-select-none tw-items-center tw-justify-center tw-rounded-xl tw-border tw-border-solid tw-text-base tw-font-semibold tw-transition-all ${
              active
                ? "tw-border-[#854ec9] tw-bg-[#854ec9] tw-text-white tw-shadow-[0_6px_16px_rgba(133,78,201,0.35)]"
                : "tw-border-[#e2dded] tw-bg-white tw-text-[#5d556c] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]"
            }`}
          >
            <input
              type="radio"
              name={name}
              className="tw-sr-only"
              checked={active}
              onChange={() => onChange(String(n))}
            />
            {n}
          </label>
        );
      })}
    </div>
  );
}

function ChoicePills({
  name,
  options,
  value,
  onChange,
}: {
  name: string;
  options: { value: string; label: string }[];
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <div className="tw-flex tw-flex-wrap tw-gap-2">
      {options.map((opt) => {
        const active = String(value) === String(opt.value);
        return (
          <label
            key={opt.value}
            className={`tw-cursor-pointer tw-select-none tw-rounded-full tw-border tw-border-solid tw-px-4 tw-py-2 tw-text-sm tw-font-medium tw-transition-all ${
              active
                ? "tw-border-[#854ec9] tw-bg-[#854ec9] tw-text-white tw-shadow-[0_6px_16px_rgba(133,78,201,0.30)]"
                : "tw-border-[#e2dded] tw-bg-white tw-text-[#5d556c] hover:tw-border-[#854ec9] hover:tw-text-[#854ec9]"
            }`}
          >
            <input
              type="radio"
              name={name}
              className="tw-sr-only"
              checked={active}
              onChange={() => onChange(opt.value)}
            />
            {opt.label}
          </label>
        );
      })}
    </div>
  );
}

export default function ReviewPage({ locations }: { locations: any }) {
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [submitStatus, setSubmitStatus] = useState("");
  const [phoneCode, setPhoneCode] = useState("");
  const [phone, setPhone] = useState("");

  const [formData, setFormData] = useState({
    name: "",
    surname: "",
    company: "",
    country: "",
    email: "",
    phone: "",
    consultant: "",
    pax: "",
    bookingBefore: "",
    question1: "",
    question2: "",
    question3: "",
    question4: "",
    comment: "",
  });

  const submitForm = async () => {
    if (
      formData.name &&
      formData.surname &&
      formData.company &&
      formData.country &&
      formData.email &&
      formData.phone &&
      formData.consultant &&
      formData.pax &&
      formData.bookingBefore &&
      formData.question1 &&
      formData.question2 &&
      formData.question3 &&
      formData.question4
    ) {
      if (parseInt(formData.pax) > 10000) {
        setErrorMessage("Pax can be max 10,000.");
        setSubmitStatus("error");
        setTimeout(() => {
          window.scrollTo(0, 0);
        }, 0);
      } else {
        setErrorMessage("");
        setSubmitStatus("");

        try {
          setLoading(true);

          const res = await sendReviewConsultantForm({ data: formData });

          if (res.success) {
            setSubmitStatus("success");
          } else {
            setSubmitStatus("error");
            setErrorMessage(res.errors[Object.keys(res.errors)[0]][0]);
          }
        } catch (error: any) {
          setSubmitStatus("error");
          setErrorMessage(
            "Error while sending form. Please check the form and try again."
          );
        } finally {
          setLoading(false);
          setTimeout(() => {
            window.scrollTo(0, 0);
          }, 0);
        }
      }
    } else {
      setErrorMessage("Please fill in the required fields.");
      setSubmitStatus("error");
      setTimeout(() => {
        window.scrollTo(0, 0);
      }, 0);
    }
  };

  return (
    <main>
      <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4 tw-my-8">
        <Breadcrumb
          items={[
            { pageTitle: "Review Consultant", pageUrl: "/review-consultant" },
          ]}
        />

        <div className="tw-mx-auto tw-mb-8 tw-max-w-2xl tw-text-center">
          <span className="tw-inline-block tw-rounded-full tw-bg-[#854ec9]/10 tw-px-4 tw-py-1.5 tw-text-xs tw-font-bold tw-uppercase tw-tracking-wide tw-text-[#854ec9]">
            Consultant Review
          </span>
          <h1 className="tw-font-display tw-mt-4 tw-mb-0 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
            We&apos;d love your feedback
          </h1>
          <p className="tw-mx-auto tw-mt-2 tw-mb-0 tw-max-w-[56ch] tw-text-sm tw-text-[#6b6577]">
            Please take a moment to share your valuable insight on our services.
            Your feedback helps us serve you better.
          </p>
        </div>

        <div className="tw-mx-auto tw-max-w-3xl">
          <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_14px_34px_rgba(20,16,28,0.06)]">
            {submitStatus === "success" && (
              <div className="tw-p-8 tw-text-center">
                <div className="tw-mx-auto tw-mb-4 tw-flex tw-h-16 tw-w-16 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#e8f7ee] tw-text-[#1a9c54]">
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="36"
                    height="36"
                    fill="currentColor"
                    viewBox="0 0 16 16"
                  >
                    <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
                    <path d="M10.97 4.97a.235.235 0 0 0-.02.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-1.071-1.05z" />
                  </svg>
                </div>
                <h2 className="tw-font-display tw-m-0 tw-text-2xl tw-font-bold tw-text-[#14101c]">
                  Thank you!
                </h2>
                <div className="tw-mx-auto tw-mt-4 tw-max-w-[58ch] tw-space-y-3 tw-text-sm tw-leading-relaxed tw-text-[#5d556c]">
                  <p className="tw-m-0">Dear Esteemed Colleagues,</p>
                  <p className="tw-m-0">
                    Thank you for participating in our survey. Your feedback is
                    very valuable to us and we wanted to take a moment to express
                    our sincere request that you continue to share your opinions
                    and ideas with us — this will help us improve our services.
                    Your comments and suggestions give us valuable insight and
                    we look forward to your participation and feedback.
                  </p>
                  <p className="tw-m-0">
                    Best Regards,
                    <br />
                    TravelShop Turkey &amp; Team
                    <br />
                    www.travelshopbooking.com
                  </p>
                </div>
              </div>
            )}

            {submitStatus !== "success" && (
              <form className="tw-grid tw-grid-cols-1 tw-gap-5 tw-p-6 md:tw-grid-cols-2 md:tw-p-8">
                {errorMessage && (
                  <div
                    className="tw-rounded-xl tw-border-0 tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-font-medium tw-text-[#b3261e] md:tw-col-span-2"
                    role="alert"
                  >
                    {errorMessage}
                  </div>
                )}

                <div>
                  <label htmlFor="name" className={labelCls}>
                    Name <RequiredMark />
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="name"
                    onChange={(event: any) => {
                      setFormData({ ...formData, name: event.target.value });
                    }}
                  />
                </div>

                <div>
                  <label htmlFor="surname" className={labelCls}>
                    Surname <RequiredMark />
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="surname"
                    onChange={(event: any) => {
                      setFormData({ ...formData, surname: event.target.value });
                    }}
                  />
                </div>

                <div>
                  <label htmlFor="company" className={labelCls}>
                    Company <RequiredMark />
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="company"
                    onChange={(event: any) => {
                      setFormData({ ...formData, company: event.target.value });
                    }}
                  />
                </div>

                <div>
                  <label htmlFor="country" className={labelCls}>
                    Country <RequiredMark />
                  </label>
                  <select
                    id="country"
                    className={inputCls}
                    onChange={(event: any) => {
                      setFormData({
                        ...formData,
                        country: event.target.value,
                        phone: "",
                      });
                      setPhone("");
                      setPhoneCode(
                        locations.find((x: any) => x.id == event.target.value)!
                          .phone_code
                      );
                    }}
                    defaultValue={""}
                  >
                    <option value="">Choose...</option>
                    {locations
                      .sort(function (a: any, b: any) {
                        if (a.name < b.name) {
                          return -1;
                        }
                        if (a.name > b.name) {
                          return 1;
                        }
                        return 0;
                      })
                      .map((item: any) => (
                        <option value={item.id} key={item.id}>
                          {item.name}
                        </option>
                      ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="emailAddress" className={labelCls}>
                    E-mail Address <RequiredMark />
                  </label>
                  <input
                    type="text"
                    className={inputCls}
                    id="emailAddress"
                    onChange={(event: any) => {
                      setFormData({ ...formData, email: event.target.value });
                    }}
                  />
                </div>

                <div>
                  <label htmlFor="mobileNumber" className={labelCls}>
                    Mobile Number <RequiredMark />
                  </label>
                  <div className="tw-flex tw-overflow-hidden tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-transition focus-within:tw-border-[#854ec9] focus-within:tw-shadow-[0_0_0_3px_rgba(133,78,201,0.12)]">
                    <span className="tw-flex tw-items-center tw-border-0 tw-border-r tw-border-solid tw-border-[#d6d2de] tw-bg-[#f6f4fa] tw-px-3 tw-text-sm tw-text-[#5d556c]">
                      {phoneCode || "—"}
                    </span>
                    <MaskedInput
                      id="mobileNumber"
                      className="tw-min-w-0 tw-flex-1 tw-border-0 tw-px-3.5 tw-py-2.5 tw-text-sm tw-text-[#14101c] tw-outline-none"
                      maskGenerator={createDefaultMaskGenerator(
                        "999999999999999999999"
                      )}
                      autoComplete="off"
                      value={phone}
                      onChange={(val) => {
                        setPhone(val);
                        setFormData({ ...formData, phone: phoneCode + val });
                      }}
                    />
                  </div>
                </div>

                <div>
                  <label htmlFor="consultantName" className={labelCls}>
                    What is your tour consultant name? <RequiredMark />
                  </label>
                  <select
                    id="consultantName"
                    className={inputCls}
                    onChange={(event: any) => {
                      setFormData({
                        ...formData,
                        consultant: event.target.value,
                      });
                    }}
                    defaultValue={""}
                  >
                    <option value="">Choose...</option>
                    {CONSULTANTS.map((c) => (
                      <option value={c.value} key={c.value}>
                        {c.label}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label htmlFor="pax" className={labelCls}>
                    How many pax do you have in your enquire? <RequiredMark />
                  </label>
                  <MaskedInput
                    id="pax"
                    className={inputCls}
                    maskGenerator={createDefaultMaskGenerator("99999")}
                    autoComplete="off"
                    value={formData.pax}
                    onChange={(val) => {
                      setFormData({ ...formData, pax: val });
                    }}
                  />
                </div>

                <div className="md:tw-col-span-2">
                  <label htmlFor="bookingBefore" className={labelCls}>
                    Have you booked this request / inquiry with us?{" "}
                    <RequiredMark />
                  </label>
                  <ChoicePills
                    name="bookingBeforeRadios"
                    options={BOOKING_OPTIONS}
                    value={formData.bookingBefore}
                    onChange={(v) =>
                      setFormData({ ...formData, bookingBefore: v })
                    }
                  />
                </div>

                <div className="tw-rounded-xl tw-bg-[#f6f4fa] tw-px-4 tw-py-4 tw-text-center md:tw-col-span-2">
                  <h3 className="tw-font-display tw-m-0 tw-text-lg tw-font-bold tw-text-[#14101c]">
                    Please Rate Us
                  </h3>
                  <p className="tw-mx-auto tw-mt-1 tw-mb-0 tw-max-w-[60ch] tw-text-xs tw-text-[#6b6577]">
                    1 – Not satisfied · 2 – Okay, not helpful · 3 – Satisfied · 4
                    – Very satisfied · 5 – Impressive
                  </p>
                </div>

                {QUESTIONS.map((q) => (
                  <div key={q.key} className="md:tw-col-span-2">
                    <label className={labelCls}>
                      {q.label} <RequiredMark />
                    </label>
                    <RatingScale
                      name={q.key}
                      value={(formData as any)[q.key]}
                      onChange={(v) =>
                        setFormData({ ...formData, [q.key]: v })
                      }
                    />
                  </div>
                ))}

                <div className="md:tw-col-span-2">
                  <label htmlFor="comment" className={labelCls}>
                    Please write your comments and suggestions:
                  </label>
                  <textarea
                    className={`${inputCls} tw-min-h-[120px] tw-resize-y`}
                    id="comment"
                    onChange={(event: any) => {
                      setFormData({ ...formData, comment: event.target.value });
                    }}
                  ></textarea>
                </div>

                <div className="md:tw-col-span-2">
                  <button
                    type="button"
                    className="tw-flex tw-w-full tw-cursor-pointer tw-items-center tw-justify-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-py-3 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#6a3da4] disabled:tw-cursor-not-allowed disabled:tw-opacity-70"
                    onClick={submitForm}
                    disabled={loading}
                  >
                    {loading && (
                      <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                    )}
                    {loading ? "Loading..." : "Submit"}
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
