import { apiClient } from "@/lib/apiClient";

// apiv3 B2C: POST /b2c/review-consultant — tur danışmanı anketi (anonim). {success:true} döner.
export default async function sendReviewConsultantForm({ data }: { data: any }) {
  return apiClient("/b2c/review-consultant", {
    method: "POST",
    body: data,
  });
}
